from .repository import has_contact, put_contact


def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)


def import_contacts(connection, rows):
    if not isinstance(rows, list):
        raise ValueError("Contacts must be a list")

    contacts = []
    emails = set()
    for row in rows:
        if not isinstance(row, dict) or set(row) != {"email", "name"}:
            raise ValueError("Each contact must contain exactly email and name")
        email, name = row["email"], row["name"]
        if not isinstance(email, str) or not isinstance(name, str):
            raise ValueError("Email and name must be strings")
        email, name = email.strip().lower(), name.strip()
        if (email.count("@") != 1 or email.startswith("@")
                or email.endswith("@") or any(char.isspace() for char in email)):
            raise ValueError("Invalid email")
        if not name:
            raise ValueError("Name must not be empty")
        if email in emails:
            raise ValueError("Duplicate email in batch")
        emails.add(email)
        contacts.append((email, name))

    summary = {"inserted": 0, "updated": 0}
    if not contacts:
        return summary

    with connection:
        # Explicitly begin so the batch is atomic even in autocommit mode.
        connection.execute("BEGIN")
        for email, name in contacts:
            key = "updated" if has_contact(connection, email) else "inserted"
            put_contact(connection, email, name)
            summary[key] += 1
    return summary
